import pytest

from sales_dashboard.report import campaign_summary, top_converting_groups


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_campaign_summary_pooled_rounded_rate_and_calendar_window(days, recent):
    groups = {
        "small": [{"day": 1, "converted": True}],
        "large": [
            {"day": 4, "converted": True},
            {"day": 5, "converted": False},
            {"day": 5, "converted": None},
            {"day": 1, "converted": False},
            {"day": 2, "converted": False},
        ],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]),
                                         (10, ["best", "a", "z", "zero"])])
def test_top_converting_groups_ranking_ties_and_empty_groups(n, expected):
    groups = {
        "z": [{"converted": True}, {"converted": None}],
        "empty": [],
        "zero": [{"converted": False}],
        "a": [{"converted": True}, {"converted": False}],
        "best": [{"converted": True}],
    }
    assert top_converting_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_converting_groups_no_sessions(groups):
    assert top_converting_groups(groups, 5) == []
